CREATE OR REPLACE FUNCTION get_sessions_duration_minutes(p_sessions_id TEXT)
RETURNS INTEGER AS $$
  SELECT (SELECT duration_minutes FROM sessions WHERE sessions_id = p_sessions_id);
$$ LANGUAGE sql STABLE;

-- get_sessions_mood_rating
-- Helper function: Get MoodRating from Sessions by SessionsId
-- Used for join-free cross-table references in aggregations

CREATE OR REPLACE FUNCTION get_sessions_mood_rating(p_sessions_id TEXT)
RETURNS INTEGER AS $$
  SELECT (SELECT mood_rating FROM sessions WHERE sessions_id = p_sessions_id);
$$ LANGUAGE sql STABLE;

-- get_sessions_notes
-- Helper function: Get Notes from Sessions by SessionsId
-- Used for join-free cross-table references in aggregations
CREATE OR REPLACE FUNCTION get_sessions_notes(p_sessions_id TEXT)
RETURNS TEXT AS $$
  SELECT (SELECT notes FROM sessions WHERE sessions_id = p_sessions_id);
$$ LANGUAGE sql STABLE;

-- calc_goal_updates_name
-- Field: GoalUpdates.Name
-- Type: calculated | DataType: string | Returns: TEXT

CREATE OR REPLACE FUNCTION calc_goal_updates_name(p_goal_updates_id TEXT)
RETURNS TEXT AS $$
  SELECT ((SELECT NULLIF(goal_updates_id, '') FROM goal_updates WHERE goal_updates_id = p_goal_updates_id))::text;
$$ LANGUAGE sql STABLE;

